"""Test 9, the execution-span check, the comparisons (items 2 and 3 of the span-check prompt), from spans-t9.json and the
fits already written; nothing recomputed from the counts. Definitions, fixed here:
  - a repeat's spans: the spans its 16 positions (2 + 16 (r - 1) to 2 + 16 r - 1) ran in, from each span's positions;
  - a span boundary, in jobs 2 and 3: the change from one span to the next in start order; the boundary's repeat is the
    first repeat whose first position ran in the later span (the first repeat that begins after the earlier span ends);
  - a change point: each change repeat of the best two-level pattern (scan_t9's), for every STEPPED and MOVING qubit;
    its position, the first position of that repeat; at a boundary if it is a boundary's repeat, within one repeat if
    one repeat off one, elsewhere otherwise;
  - in jobs with interleaved positions (test 9's job 1, test 8's jobs 1 and 3, test 7's job), the span boundaries as
    the first position of each later span, beside the ten blocks of 26 positions of the weight in execution order, and
    beside each named qubit's implied weight at the positions nearest each boundary (those passing the lever).
Writes span-compare-t9.json and prints the tables."""
import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
SP = {(j["test"], j["job"]): j for j in json.loads((HERE / "spans-t9.json").read_text())["jobs"]}


def span_of(job):
    m = {}
    for s in job["spans"]:
        for p in s["positions"]:
            m[p] = s["span"]
    return m


def scan_side(test, jn, fits):
    job = SP[(test, jn)]
    m = span_of(job)
    order = job["spans_in_start_order"]
    rank = {s: i for i, s in enumerate(order)}
    rep = {r: sorted({rank[m[p]] for p in range(2 + 16 * (r - 1), 2 + 16 * r)}) for r in range(1, 19)}
    bounds = []
    for b in range(1, len(order)):
        first = next(r for r in range(1, 19) if rank[m[2 + 16 * (r - 1)]] >= b)
        bounds.append({"between_spans_in_start_order": [b - 1, b], "first_position_of_later_span": min(job["spans"][order[b]]["positions"]),
                       "boundary_repeat": first, "boundary_repeat_first_position": 2 + 16 * (first - 1)})
    br = [x["boundary_repeat"] for x in bounds]
    rows = []
    f = json.loads((HERE / fits).read_text())
    for q, v in sorted(f["qubits"].items(), key=lambda x: int(x[0])):
        if v["verdict"] not in ("STEPPED", "MOVING"):
            continue
        t = v["models"]["two_levels"]
        for r in t["change_repeats"]:
            d = min(abs(r - b) for b in br)
            rows.append({"job": jn, "qubit": int(q), "verdict": v["verdict"], "pattern": t["pattern"], "change_repeat": r, "change_position": 2 + 16 * (r - 1),
                         "spans_of_repeat_before": rep.get(r - 1), "spans_of_change_repeat": rep[r],
                         "class": "at a boundary" if d == 0 else ("within one repeat of one" if d == 1 else "elsewhere")})
    return {"repeat_spans_in_start_order": rep, "boundaries": bounds, "changes": rows}


def interleaved_side(test, jn, weights):
    job = SP[(test, jn)]
    order = job["spans_in_start_order"]
    firsts = [min(job["spans"][order[b]]["positions"]) for b in range(1, len(order))]
    blocks = [[26 * k, 26 * k + 25] for k in range(10)]
    out = {"span_position_runs_in_start_order": [job["spans"][i]["position_runs"] for i in order], "boundaries_first_position": firsts,
           "boundary_in_block": [next(k for k, b in enumerate(blocks) if b[0] <= p <= b[1]) + 1 for p in firsts], "qubits": {}}
    for name, w in weights.items():
        if not w:
            continue
        pos = sorted(w["positions"], key=lambda r: r["k"])
        near = {}
        for p in firsts:
            before = [r for r in pos if r["k"] < p][-3:]
            after = [r for r in pos if r["k"] >= p][:3]
            near[str(p)] = {"before": [(r["k"], round(r["b_pos"], 3)) for r in before], "after": [(r["k"], round(r["b_pos"], 3)) for r in after]}
        out["qubits"][name] = {"blocks": [None if b.get("weighted_mean") is None else round(b["weighted_mean"], 3) for b in w["blocks_or_list"]], "near_boundaries": near}
    return out


def t_blocks(fits, q):
    w = json.loads((HERE.parent / fits).read_text())["qubits"][q]["weight_in_execution_order"]
    if not w:
        return None
    return {"blocks_or_list": w["blocks"], "positions": w["positions"]}


def t7_blocks():
    r = json.loads((HERE.parent / "hardware-t7" / "reading-t7.json").read_text())["B_weight_in_execution_order"]
    return {"blocks_or_list": [{"weighted_mean": b["weighted_mean"]} for b in r["blocks_of_26"]], "positions": r["positions"]}


def main():
    out = {"scan": {"job2": scan_side("t9", 2, "fits-t9-job2.json"), "job3": scan_side("t9", 3, "fits-t9-job3.json")},
           "interleaved": {
               "t9_job1": interleaved_side("t9", 1, {"43": t_blocks("hardware-t9/fits-t9-job1.json", "43"), "134": t_blocks("hardware-t9/fits-t9-job1.json", "134")}),
               "t8_job1": interleaved_side("t8", 1, {"43": t_blocks("hardware-t8/fits-t8-job1.json", "43"), "134": t_blocks("hardware-t8/fits-t8-job1.json", "134")}),
               "t8_job3": interleaved_side("t8", 3, {"43": t_blocks("hardware-t8/fits-t8-job3.json", "43"), "134": t_blocks("hardware-t8/fits-t8-job3.json", "134")}),
               "t7": interleaved_side("t7", 1, {"143": t7_blocks()})}}
    (HERE / "span-compare-t9.json").write_text(json.dumps({"note": __doc__, **out}, indent=1))
    for k in ("job2", "job3"):
        s = out["scan"][k]
        print(k, "boundaries", s["boundaries"])
        print(" repeats spanning two spans", {r: v for r, v in s["repeat_spans_in_start_order"].items() if len(v) > 1})
        for r in s["changes"]:
            print(" ", r["qubit"], r["verdict"], r["pattern"], r["change_repeat"], r["change_position"], r["spans_of_change_repeat"], r["class"])
    for k, v in out["interleaved"].items():
        print(k, v["span_position_runs_in_start_order"], v["boundaries_first_position"], "blocks", v["boundary_in_block"])
        for q, x in v["qubits"].items():
            print("  ", q, x["blocks"], x["near_boundaries"])


if __name__ == "__main__":
    main()
